from flask import Flask, request, Response
import socket
import re

app = Flask(__name__)

# Internal microservice proxy - forwards requests to backend API
BACKEND_HOST = "internal-api.service.local"
BACKEND_PORT = 8080

def forward_to_backend(method, path, headers, body):
    """Raw socket forwarding to preserve original request semantics"""
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)
    sock.connect((BACKEND_HOST, BACKEND_PORT))

    # Build raw HTTP request - preserves both Content-Length and 
    # Transfer-Encoding if present (needed for chunked upload support)
    raw_request = f"{method} {path} HTTP/1.1\r\n"
    raw_request += f"Host: {BACKEND_HOST}:{BACKEND_PORT}\r\n"

    # Forward all original headers to maintain client intent
    skip_headers = {'host'}
    for key, value in headers.items():
        if key.lower() not in skip_headers:
            raw_request += f"{key}: {value}\r\n"

    raw_request += "\r\n"
    if body:
        raw_request += body

    sock.sendall(raw_request.encode('latin-1'))

    # Read response
    response_data = b""
    while True:
        try:
            chunk = sock.recv(4096)
            if not chunk:
                break
            response_data += chunk
        except socket.timeout:
            break

    sock.close()
    return response_data

def parse_response(raw_response):
    """Parse raw HTTP response back into Flask response"""
    try:
        header_end = raw_response.find(b"\r\n\r\n")
        if header_end == -1:
            return Response("Bad Gateway", status=502)

        header_section = raw_response[:header_end].decode('latin-1')
        body = raw_response[header_end + 4:]

        lines = header_section.split("\r\n")
        status_match = re.match(r'HTTP/\d\.\d (\d+)', lines[0])
        status_code = int(status_match.group(1)) if status_match else 502

        resp_headers = {}
        for line in lines[1:]:
            if ':' in line:
                k, v = line.split(':', 1)
                resp_headers[k.strip()] = v.strip()

        return Response(body, status=status_code, headers=resp_headers)
    except Exception:
        return Response("Bad Gateway", status=502)

@app.route('/api/<path:path>', methods=['GET', 'POST', 'PUT', 'DELETE', 'PATCH'])
def proxy(path):
    """Proxy endpoint for internal API access"""
    body = request.get_data(as_text=True)
    raw_resp = forward_to_backend(request.method, f"/api/{path}", request.headers, body)
    return parse_response(raw_resp)

@app.route('/health')
def health():
    return Response("OK", status=200)

@app.route('/admin/cache/purge', methods=['POST'])
def purge_cache():
    """Admin endpoint - purge internal cache. Restricted by infra controls."""
    # No application-level auth - relies on network-level restriction
    return Response('{"status": "cache purged"}', status=200, content_type='application/json')

@app.route('/admin/config', methods=['GET', 'POST'])
def admin_config():
    """Admin endpoint - view/modify runtime config. Restricted by infra controls."""
    if request.method == 'POST':
        # Dangerous: allows runtime config changes
        return Response('{"status": "config updated"}', status=200, content_type='application/json')
    return Response('{"debug": false, "rate_limit": 1000}', status=200, content_type='application/json')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
